// @supabase/functions-js shim
// This shim provides compatibility for @supabase/supabase-js

export class FunctionsClient {
  protected url;
  protected headers;
  protected fetch;
  protected region;

  constructor(url, { headers = {}, customFetch, region } = {}) {
    this.url = url;
    this.headers = { ...headers };
    this.fetch = customFetch || globalThis.fetch;
    this.region = region;
  }

  setAuth(token) {
    this.headers['Authorization'] = `Bearer ${token}`;
  }

  async invoke(functionName, options = {}) {
    const { headers = {}, method = 'POST', body, region } = options;
    const invokeRegion = region || this.region;

    let _headers = {
      ...this.headers,
      ...headers,
    };

    let _body;
    if (
      body &&
      !(body instanceof Blob) &&
      !(body instanceof ArrayBuffer) &&
      !(body instanceof FormData) &&
      !(body instanceof URLSearchParams) &&
      (typeof body !== 'string' || !_headers['Content-Type'])
    ) {
      _body = JSON.stringify(body);
      if (!_headers['Content-Type']) {
        _headers['Content-Type'] = 'application/json';
      }
    } else {
      _body = body;
    }

    let basePath = this.url;
    if (invokeRegion) {
      basePath = basePath.replace(/^(https?:\/\/)([^.]+)/, `$1${invokeRegion}.$2`);
    }

    const response = await this.fetch(`${basePath}/${functionName}`, {
      method,
      headers: _headers,
      body: _body,
    });

    const isRelayError = response.headers.get('x-relay-error');
    if (isRelayError) {
      return { data: null, error: new FunctionsRelayError(response) };
    }

    if (!response.ok) {
      return { data: null, error: new FunctionsHttpError(response) };
    }

    let data;
    const responseType = (response.headers.get('Content-Type') || 'text/plain').split(';')[0].trim();

    if (responseType === 'application/json') {
      data = await response.json();
    } else if (responseType === 'application/octet-stream') {
      data = await response.blob();
    } else if (responseType === 'text/event-stream') {
      data = response;
    } else if (responseType === 'multipart/form-data') {
      data = await response.formData();
    } else {
      data = await response.text();
    }

    return { data, error: null };
  }
}

export class FunctionsHttpError extends Error {
  context;
  constructor(context) {
    super('FunctionsHttpError: Failed to send a request to the Edge Function');
    this.name = 'FunctionsHttpError';
    this.context = context;
  }
}

export class FunctionsRelayError extends Error {
  context;
  constructor(context) {
    super('FunctionsRelayError: Failed to relay the request to the Edge Function');
    this.name = 'FunctionsRelayError';
    this.context = context;
  }
}

export class FunctionsFetchError extends Error {
  context;
  constructor(context) {
    super('FunctionsFetchError: Failed to send a request to the Edge Function');
    this.name = 'FunctionsFetchError';
    this.context = context;
  }
}
